test('renderInvoiceText shows voucher before total', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const r2 = applyVoucher(r1.value, { code: 'SAVE10', amount: 5000 });
  const text = renderInvoiceText(r2.value);
  const lines = text.split('\n');
  const voucherIndex = lines.findIndex(l => l.includes('Voucher'));
  const totalIndex = lines.findIndex(l => l.startsWith('Total'));
  assert(voucherIndex > 0);
  assert(totalIndex > voucherIndex);
  assert.equal(lines[voucherIndex], 'Voucher: €50.00');
});

