    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const r2 = recordPayment(r1.value, { amount: 5000, date: '2026-10-15' });
  const text = renderInvoiceText(r2.value);
  const lines = text.split('\n');
  assert(lines.some(l => l.includes('Paid:')));
  assert.equal(lines[lines.length - 1], 'Paid: €50.00');
});

test('renderInvoiceText aggregates multiple payments', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = recordPayment(r1.value, { amount: 10000, date: '2026-10-15' });
  const r3 = recordPayment(r2.value, { amount: 10000, date: '2026-10-20' });
  const text = renderInvoiceText(r3.value);
  assert(text.includes('Paid: €200.00'));
});

test('renderInvoiceText does not show paid when no payments', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const text = renderInvoiceText(r.value);
  assert(!text.includes('Paid:'));
});

test('renderInvoiceText with all enhanced features', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 10 }],
  });
  const r2 = applyVoucher(r1.value, { code: 'SAVE', amount: 3000 });
  const r3 = recordPayment(r2.value, { amount: 20000, date: '2026-10-15' });
  const text = renderInvoiceText(r3.value);
  const lines = text.split('\n');

  assert(lines.some(l => l.includes('Discount (10%)')));
  assert(lines.some(l => l.includes('Voucher:')));
  assert(lines.some(l => l.includes('Due:')));
  assert(lines.some(l => l.includes('Paid:')));
});

test('renderInvoiceText line discount with bulk discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  assert(lines.some(l => l.includes('Discount (5%)')));
});

test('renderInvoiceText shows discount percent correctly', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 15 }],
  });
  const text = renderInvoiceText(r.value);
  assert(text.includes('Discount (15%)'));
});

test('renderInvoiceText order: lines, VAT, voucher, total, due, paid', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const r2 = applyVoucher(r1.value, { code: 'SAVE', amount: 3000 });
  const r3 = recordPayment(r2.value, { amount: 20000, date: '2026-10-15' });
  const text = renderInvoiceText(r3.value);
  const lines = text.split('\n');

  const vatIndex = lines.findIndex(l => l.startsWith('VAT'));
  const voucherIndex = lines.findIndex(l => l.startsWith('Voucher'));
  const totalIndex = lines.findIndex(l => l.startsWith('Total'));
  const dueIndex = lines.findIndex(l => l.startsWith('Due'));
  const paidIndex = lines.findIndex(l => l.startsWith('Paid'));

  assert(vatIndex < voucherIndex || voucherIndex === -1);
  assert(voucherIndex < totalIndex);
  assert(totalIndex < dueIndex);
  assert(dueIndex < paidIndex);
});

test('renderInvoiceText with no VAT, voucher, or payments', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1, discountPercent: 0 }],
  });
  const text = renderInvoiceText(r.value);
  assert(!text.includes('VAT'));
  assert(!text.includes('Voucher'));
  assert(!text.includes('Paid'));
  assert(text.includes('Total'));
  assert(text.includes('Due'));
});

