test('renderInvoiceText shows correct total', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'ICON-SET', qty: 10 },
      { sku: 'STICKER', qty: 100 },
    ],
  });
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  // ICON-SET: 10 * 980 = 9800
  // STICKER: 100 * 50 = 5000
  // Subtotal: 14800
  // Gold tier discount (5%): 490 + 250 = 740
  // Bulk discount (2.5% after line discount):
  //   ICON-SET: (9800 - 490) * 2.5% = 233
