  const lines = text.split('\n');
  assert.equal(lines[1], 'Kite & Co');
});

test('renderInvoiceText formats line items correctly', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  assert.equal(lines[2], '  5x Design work (hour) @ €85.00 = €425.00');
});

test('renderInvoiceText with multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  // DRAFT + customer + 2 line items + 2 discounts + VAT + total + due
  assert.equal(lines[0], 'DRAFT');
  assert.equal(lines[1], 'Acme Innovations');
  assert.equal(lines[2], '  5x Design work (hour) @ €85.00 = €425.00');
  assert(lines[3].includes('Discount'));
  assert.equal(lines[4], '  3x Development (hour) @ €95.00 = €285.00');
  assert(lines[5].includes('Discount'));
  assert(lines[lines.length - 3].includes('VAT'));
  assert(lines[lines.length - 2].startsWith('Total'));
  assert(lines[lines.length - 1].startsWith('Due'));
});

test('renderInvoiceText shows correct total', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'ICON-SET', qty: 10 },
      { sku: 'STICKER', qty: 100 },
    ],
  });
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  // ICON-SET: 10 * 980 = 9800
  // STICKER: 100 * 50 = 5000
  // Subtotal: 14800
  // Gold tier discount (5%): 490 + 250 = 740
  // Bulk discount (2.5% after line discount):
  //   ICON-SET: (9800 - 490) * 2.5% = 233
  //   STICKER: (5000 - 250) * 2.5% = 119
  // Total discount: 740 + 233 + 119 = 1092
  // Amount after discount: 14800 - 1092 = 13708
  // VAT (21%): roundCents(9077 * 21 / 100) + roundCents(4631 * 21 / 100) = 1906 + 973 = 2879
  // Total: 13708 + 2879 = 16587 = €165.87
  assert(text.includes('VAT: €28.79'));
  assert(text.includes('Total: €165.87'));
});

test('renderInvoiceText with VAT-exempt products', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'WORKSHOP-DAY', qty: 2 },
    ],
  });
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  assert(text.includes('2x Brand workshop (day, VAT exempt) @ €600.00 = €1,200.00'));
  // Gold tier discount (5%): 120000 * 0.05 = 6000 = €60
  // Total: €1,200.00 - €60.00 = €1,140.00
  assert(text.includes('Total: €1,140.00'));
});

test('renderInvoiceText with issued invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-010',
    issueDate: '2025-12-31',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  const r2 = issueInvoice(r1.value, ['INV-2025-0001']);
  const text = renderInvoiceText(r2.value);
  const lines = text.split('\n');
  assert.equal(lines[0], 'INV-2025-0002');
  assert.equal(lines[1], 'Tidewater Museum');
  assert(text.includes('1x Logo package @ €1,200.00 = €1,200.00'));
  // Silver tier discount (2.5%): 120000 * 0.025 = 3000 = €30
  // Amount after discount: 117000 cents
  // VAT (21%): 24570 cents = €245.70
  // Total: €1,200.00 - €30.00 + €245.70 = €1,415.70
  assert(text.includes('VAT: €245.70'));
  assert(text.includes('Total: €1,415.70'));
});

test('renderInvoiceText with single low-price item', () => {
